-- ES/DE/FR translations for all 9 Ireland milestones.
-- ie-phase1 and ie-phase2 reuse the tracker's own phrasing (not
-- re-translated separately) per tracker-phrasing-wins.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-peppol-authority-2018', 'es', 'La Oficina de Contratación Pública se convierte en la Autoridad Peppol de Irlanda', 'OGP asume la responsabilidad de la infraestructura técnica y de contratación que conecta a los organismos públicos irlandeses con Peppol — años antes de que existiera ninguna política B2B general.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-peppol-authority-2018', 'de', 'Das Office of Government Procurement wird zur irischen Peppol-Behörde', 'OGP übernimmt die Verantwortung für die technische und beschaffungsbezogene Infrastruktur, die irische öffentliche Stellen mit Peppol verbindet — Jahre bevor es überhaupt eine allgemeine B2B-Politik gab.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-peppol-authority-2018', 'fr', 'Le Office of Government Procurement devient l''autorité Peppol irlandaise', 'L''OGP prend en charge l''infrastructure technique et d''approvisionnement reliant les organismes publics irlandais à Peppol — des années avant qu''une quelconque politique B2B générale n''existe.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-b2g-mandatory-2020', 'es', 'Todas las entidades del sector público deben poder recibir facturas electrónicas', 'Un precedente B2G real al que las empresas de la Fase 1 pueden remitirse directamente — los organismos públicos irlandeses llevan años procesando facturas Peppol estructuradas.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-b2g-mandatory-2020', 'de', 'Alle Einrichtungen des öffentlichen Sektors müssen E-Rechnungen empfangen können', 'Ein funktionierender B2G-Präzedenzfall, auf den sich Phase-1-Unternehmen direkt berufen können — irische öffentliche Stellen verarbeiten bereits seit Jahren strukturierte Peppol-Rechnungen.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-b2g-mandatory-2020', 'fr', 'Toutes les entités du secteur public doivent pouvoir recevoir des factures électroniques', 'Un précédent B2G concret sur lequel les entreprises de la Phase 1 peuvent s''appuyer directement — les organismes publics irlandais traitent des factures Peppol structurées depuis des années déjà.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-consultation-2023', 'es', 'La Administración Tributaria (Revenue) realiza una consulta pública', 'Recoge las opiniones de las partes interesadas sobre el reporte digital de IVA en tiempo real y la facturación electrónica, tras el anuncio del Presupuesto 2024 del ministro de Finanzas Michael McGrath.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-consultation-2023', 'de', 'Die Revenue Commissioners führen eine öffentliche Konsultation durch', 'Einholung von Stellungnahmen der Interessengruppen zur digitalen Echtzeit-Umsatzsteuermeldung und elektronischen Rechnungsstellung, im Anschluss an die Ankündigung von Finanzminister Michael McGrath im Haushalt 2024.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-consultation-2023', 'fr', 'Les Revenue Commissioners mènent une consultation publique', 'Recueil des avis des parties prenantes sur la déclaration numérique de TVA en temps réel et la facturation électronique, à la suite de l''annonce du ministre des Finances Michael McGrath dans le cadre du Budget 2024.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-budget2026-confirm', 'es', 'El Presupuesto 2026 confirma el despliegue por fases; se publica el documento de Modernización del IVA', 'El ministro de Finanzas Paschal Donohoe confirma que la Administración Tributaria implementará un despliegue nacional por fases de la facturación electrónica; el documento de implementación de Revenue establece la estructura de tres fases.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-budget2026-confirm', 'de', 'Der Haushalt 2026 bestätigt den stufenweisen Rollout; das Dokument zur Umsatzsteuermodernisierung wird veröffentlicht', 'Finanzminister Paschal Donohoe bestätigt, dass Revenue einen stufenweisen nationalen Rollout der E-Rechnung umsetzen wird; das Umsetzungsdokument von Revenue legt die dreiphasige Struktur fest.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-budget2026-confirm', 'fr', 'Le Budget 2026 confirme le déploiement par phases ; le document de modernisation de la TVA est publié', 'Le ministre des Finances Paschal Donohoe confirme que Revenue mettra en œuvre un déploiement national par phases de la facturation électronique ; le document de mise en œuvre de Revenue définit la structure en trois phases.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase1-criteria-2026', 'es', 'Revenue confirma los criterios de contribuyentes de la Fase 1', '"Gran empresa" se define administrativamente — si sus asuntos fiscales son gestionados por la División de Grandes Empresas de Revenue — y no mediante un umbral público de facturación o plantilla.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase1-criteria-2026', 'de', 'Revenue bestätigt die Steuerpflichtigenkriterien für Phase 1', '"Großunternehmen" wird administrativ definiert — danach, ob Ihre Steuerangelegenheiten von der Großunternehmensabteilung von Revenue verwaltet werden — nicht anhand eines öffentlichen Umsatz- oder Mitarbeiterschwellenwerts.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase1-criteria-2026', 'fr', 'Revenue confirme les critères des contribuables de la Phase 1', '« Grande entreprise » est définie de manière administrative — selon que vos affaires fiscales sont gérées par la division des grandes entreprises de Revenue — et non par un seuil public de chiffre d''affaires ou d''effectif.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase1-criteria-reconfirmed', 'es', 'Se reconfirma el alcance de la Fase 1', 'Revenue reitera los criterios de la Fase 1 unos ocho meses después de la confirmación inicial, lo que indica que el alcance ya es estable de cara a la entrada en vigor.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase1-criteria-reconfirmed', 'de', 'Umfang von Phase 1 erneut bestätigt', 'Revenue bekräftigt die Kriterien für Phase 1 rund acht Monate nach der ursprünglichen Bestätigung und signalisiert damit, dass der Umfang vor dem Start nun stabil ist.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase1-criteria-reconfirmed', 'fr', 'Le périmètre de la Phase 1 est reconfirmé', 'Revenue réaffirme les critères de la Phase 1 environ huit mois après la confirmation initiale, signalant que le périmètre est désormais stable avant l''entrée en vigueur.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase1', 'es', 'Fase 1 — las grandes empresas deben emitir facturas electrónicas; todas las empresas deben poder recibirlas', 'Las grandes empresas registradas a efectos de IVA gestionadas por la División de Grandes Empresas de Revenue deben emitir facturas electrónicas estructuradas y reportar un subconjunto de datos de transacciones para las ventas B2B nacionales. Todas las empresas deben poder recibir técnicamente facturas electrónicas estructuradas a partir de esta fecha.', '["Grandes empresas: evalúe ahora la preparación de su ERP para la facturación estructurada EN 16931 a través de Peppol", "Todas las empresas: confirme que sus sistemas pueden recibir facturas electrónicas estructuradas — los PDF ya no serán aceptados de los proveedores incluidos en el alcance"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase1', 'de', 'Phase 1 — Großunternehmen müssen E-Rechnungen ausstellen; alle Unternehmen müssen sie empfangen können', 'Umsatzsteuerpflichtige Großunternehmen, die von der Großunternehmensabteilung von Revenue verwaltet werden, müssen strukturierte E-Rechnungen ausstellen und einen Teil der Transaktionsdaten für inländische B2B-Verkäufe melden. Alle Unternehmen müssen ab diesem Datum technisch in der Lage sein, strukturierte E-Rechnungen zu empfangen.', '["Großunternehmen: Prüfen Sie jetzt die ERP-Bereitschaft für strukturierte EN-16931-Rechnungsstellung über Peppol", "Alle Unternehmen: Bestätigen Sie, dass Ihre Systeme strukturierte E-Rechnungen empfangen können — PDFs werden von betroffenen Lieferanten nicht mehr akzeptiert"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase1', 'fr', 'Phase 1 — les grandes entreprises doivent émettre des factures électroniques ; toutes les entreprises doivent pouvoir les recevoir', 'Les grandes entreprises assujetties à la TVA gérées par la division des grandes entreprises de Revenue doivent émettre des factures électroniques structurées et déclarer un sous-ensemble de données de transaction pour les ventes B2B nationales. Toutes les entreprises doivent être techniquement capables de recevoir des factures électroniques structurées à partir de cette date.', '["Grandes entreprises : évaluez dès maintenant la préparation de votre ERP pour la facturation structurée EN 16931 via Peppol", "Toutes les entreprises : vérifiez que vos systèmes peuvent recevoir des factures électroniques structurées — les PDF ne seront plus acceptés des fournisseurs concernés"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase2', 'es', 'Fase 2 — el mandato se extiende a todas las empresas registradas a efectos de IVA en el comercio intracomunitario', 'La obligación nacional de facturación electrónica y reporte se extiende a todas las empresas restantes registradas a efectos de IVA que participan en el comercio B2B transfronterizo de la UE, antes de la plena conformidad con el ViDA de la UE en julio de 2030.', '["Las empresas que comercian de forma transfronteriza dentro de la UE deben comenzar a planificar la integración con Peppol", "Esté atento a las orientaciones detalladas de Revenue, previstas con antelación a cada fase"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase2', 'de', 'Phase 2 — die Pflicht wird auf alle umsatzsteuerpflichtigen Unternehmen im innergemeinschaftlichen Handel ausgeweitet', 'Die inländische E-Rechnungs- und Meldepflicht wird auf alle verbleibenden umsatzsteuerpflichtigen Unternehmen ausgeweitet, die am grenzüberschreitenden B2B-Handel innerhalb der EU beteiligt sind, vor der vollständigen EU-ViDA-Konformität im Juli 2030.', '["Unternehmen mit grenzüberschreitendem EU-Handel sollten mit der Planung der Peppol-Integration beginnen", "Achten Sie auf detaillierte Hinweise von Revenue, die rechtzeitig vor jeder Phase erwartet werden"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase2', 'fr', 'Phase 2 — l''obligation s''étend à toutes les entreprises assujetties à la TVA dans le commerce intracommunautaire', 'L''obligation nationale de facturation électronique et de déclaration s''étend à toutes les entreprises restantes assujetties à la TVA engagées dans le commerce B2B transfrontalier au sein de l''UE, avant la pleine conformité ViDA de l''UE en juillet 2030.', '["Les entreprises pratiquant le commerce transfrontalier au sein de l''UE devraient commencer à planifier leur intégration Peppol", "Surveillez les directives détaillées de Revenue, attendues bien avant chaque phase"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase3-vida', 'es', 'Fase 3 — requisitos transfronterizos completos del ViDA de la UE', 'Las empresas irlandesas que ya operan bajo el sistema nacional realizan la transición para cumplir con las obligaciones plenas del ViDA de la UE junto con el resto de los Estados miembros.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase3-vida', 'de', 'Phase 3 — vollständige grenzüberschreitende EU-ViDA-Anforderungen', 'Irische Unternehmen, die bereits unter dem inländischen System arbeiten, wechseln zur Erfüllung der vollständigen EU-ViDA-Pflichten gemeinsam mit allen anderen Mitgliedstaaten.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ie-phase3-vida', 'fr', 'Phase 3 — exigences transfrontalières ViDA de l''UE complètes', 'Les entreprises irlandaises déjà opérationnelles sous le système national passent au respect des obligations ViDA complètes de l''UE, aux côtés de tous les autres États membres.', '[]');
